svg.script:
(function(){
  var root=document.getElementById('male-back-exact');
  if(!root) root=document.documentElement;
  function clear(){root.querySelectorAll('.region.selected').forEach(function(e){e.classList.remove('selected');e.setAttribute('aria-pressed','false');});}
  root.querySelectorAll('.region').forEach(function(r){
    function select(){clear();r.classList.add('selected');r.setAttribute('aria-pressed','true');root.dispatchEvent(new CustomEvent('bodyRegionSelected',{detail:{regionId:r.dataset.regionId,displayName:r.dataset.displayName,view:'back'},bubbles:true}));}
    r.addEventListener('click',select);
    r.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}});
  });
})();
